fn binary_search(a: &[i32], key: i32) -> usize {
    let mut left = 0;
    let mut right = a.len();
    
    // Invariant: a[left..right] is the search space
    // We want the smallest index i in [0..a.len()] where a[i] >= key,
    // or a.len() if no such element exists.
    while left < right {
        let mid = left + (right - left) / 2;
        if a[mid] < key {
            left = mid + 1; // exclude mid and everything before
        } else {
            right = mid; // mid might be the answer, narrow right bound
        }
    }
    
    left
}